package io.infranexum.dcim.physical;
import io.infranexum.core.contracts.*;import io.infranexum.core.events.InMemoryEventStore;import io.infranexum.dcim.physical.application.*;import io.infranexum.dcim.physical.domain.*;import io.infranexum.dcim.physical.ports.*;import java.math.BigDecimal;import java.security.SecureRandom;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
/** Dependency-free vertical smoke for PGM-07-E05 occupancy, ports and cabling. */
final class DcimPhysicalApplicationServiceTest {
 private static final Clock CLOCK=Clock.fixed(Instant.parse("2026-08-15T12:00:00Z"),ZoneOffset.UTC);
 @Test void governsOccupancyPortsCablingConcurrencyAndCapability(){var repo=new Repo();var idem=new Idem();var events=new InMemoryEventStore();var ids=new UuidV7Generator(CLOCK,new SecureRandom(new byte[]{8,2,0,5}));var org=ids.next();var sub=ids.next();var room=ids.next();var manufacturer=ids.next();var rsot=ids.next();var asset=ids.next();var actor=ids.next();var corr=ids.next();var svc=new DcimPhysicalApplicationService(repo,idem,new Features(true),new Refs(org,sub,room,manufacturer,rsot,asset),events,ids,CLOCK);var ctx=new PhysicalCommandContext(actor,corr,"register governed physical infrastructure");
  var model=svc.createModel(new CreateEquipmentModelCommand(org,manufacturer,"SRV-1U","Server 1U","rack",1,482,700,new BigDecimal("12.5"),List.of(new PortTemplate("eth",2,PortKind.NETWORK,"copper","rj45")),"model"),"model-create-0001",ctx);require(model.status()==PhysicalStatus.DRAFT,"model draft");model=svc.changeModelStatus(model.id(),1,PhysicalStatus.ACTIVE,"model-active-0001",ctx);final EquipmentModel activeModel=model;
  var rack=svc.createRack(new CreateRackCommand(org,sub,room,"RACK-A","Rack A",42,600,1000),"rack-create-0001",ctx);rack=svc.changeRackStatus(rack.id(),1,PhysicalStatus.ACTIVE,"rack-active-0001",ctx);final Rack activeRack=rack;
  var e1=svc.install(new InstallEquipmentCommand(org,sub,activeRack.id(),activeModel.id(),rsot,asset,"SN-001","AT-001",10,"front"),"equip-create-0001",ctx);require(svc.ports(e1.id()).size()==2,"ports instantiated");expect("DCIM_RACK_POSITION_OCCUPIED",()->svc.install(new InstallEquipmentCommand(org,sub,activeRack.id(),activeModel.id(),ids.next(),null,"SN-002",null,10,"front"),"equip-create-0002",ctx));
  var e2=svc.install(new InstallEquipmentCommand(org,sub,activeRack.id(),activeModel.id(),ids.next(),null,"SN-003",null,12,"front"),"equip-create-0003",ctx);var p1=svc.ports(e1.id()).get(0);var p2=svc.ports(e2.id()).get(0);var cable=svc.connect(new ConnectPortsCommand(org,sub,p1.id(),p2.id(),"C-001"),"cable-create-001",ctx);require(cable.status()==PhysicalStatus.ACTIVE,"cable active");expect("DCIM_PORT_ALREADY_CONNECTED",()->svc.connect(new ConnectPortsCommand(org,sub,p1.id(),svc.ports(e2.id()).get(1).id(),"C-002"),"cable-create-002",ctx));expect("DCIM_EQUIPMENT_CABLED",()->svc.changeEquipmentStatus(e1.id(),1,PhysicalStatus.DECOMMISSIONED,"eq-decom-0001",ctx));cable=svc.disconnect(cable.id(),1,"cable-disconnect-1",ctx);require(cable.status()==PhysicalStatus.DECOMMISSIONED,"cable disconnected");var moved=svc.moveEquipment(e1.id(),1,activeRack.id(),15,"rear","equip-move-0001",ctx);require(moved.startU()==15&&"rear".equals(moved.face()),"equipment moved");require(repo.rackLocks>0&&repo.portLocks>0,"transactional allocation locks exercised");require(events.outboxSnapshot().stream().anyMatch(x->"dcim.cable.connected.v1".equals(x.event().eventType().value())),"cable event missing");var disabled=new DcimPhysicalApplicationService(repo,idem,new Features(false),new Refs(org,sub,room,manufacturer,rsot,asset),events,ids,CLOCK);expect("DCIM_PHYSICAL_CAPABILITY_UNAVAILABLE",()->disabled.models(org,10));}
 private record Features(boolean enabled) implements DcimPhysicalFeaturePolicy {public boolean physicalEnabled(){return enabled;}public long rackLimit(){return 100;}public long portLimit(){return 1000;}public long connectionLimit(){return 1000;}}
 private record Refs(DomainIdentifier org,DomainIdentifier sub,DomainIdentifier room,DomainIdentifier manufacturer,DomainIdentifier rsot,DomainIdentifier asset) implements DcimPhysicalReferencePolicy {public void requireScope(DomainIdentifier o,DomainIdentifier s){if(!org.equals(o)||!sub.equals(s))throw new DcimPhysicalConflictException("DCIM_SCOPE_MISMATCH","scope");}public void requireActiveRoom(DomainIdentifier r,DomainIdentifier o,DomainIdentifier s){requireScope(o,s);if(!room.equals(r))throw new DcimPhysicalConflictException("DCIM_ROOM_INVALID","room");}public void requireManufacturer(DomainIdentifier p,DomainIdentifier o){if(!org.equals(o)||!manufacturer.equals(p))throw new DcimPhysicalConflictException("DCIM_MANUFACTURER_INVALID","manufacturer");}public void requireRsotObject(DomainIdentifier r,DomainIdentifier o){if(!org.equals(o))throw new DcimPhysicalConflictException("DCIM_RSOT_INVALID","rsot");}public void requireItamAssetIfPresent(DomainIdentifier a,DomainIdentifier o){if(a!=null&&!org.equals(o))throw new DcimPhysicalConflictException("DCIM_ITAM_INVALID","asset");}}
 private static final class Idem implements DcimPhysicalIdempotencyRepository{final Map<String,Record> m=new HashMap<>();public Optional<Record> find(String k){return Optional.ofNullable(m.get(k));}public void insert(Record r){if(m.putIfAbsent(r.key(),r)!=null)throw new IllegalStateException("duplicate idem");}}
 private static final class Repo implements DcimPhysicalRepository {final Map<DomainIdentifier,EquipmentModel> models=new LinkedHashMap<>();final Map<DomainIdentifier,Rack> racks=new LinkedHashMap<>();final Map<DomainIdentifier,Equipment> equipment=new LinkedHashMap<>();final Map<DomainIdentifier,PhysicalPort> ports=new LinkedHashMap<>();final Map<DomainIdentifier,CableConnection> cables=new LinkedHashMap<>();int rackLocks,portLocks;public long rackCount(){return racks.size();}public long portCount(){return ports.size();}public long activeConnectionCount(){return cables.values().stream().filter(x->x.status()==PhysicalStatus.ACTIVE).count();}public boolean modelCodeExists(DomainIdentifier o,DomainIdentifier m,String c){return models.values().stream().anyMatch(x->x.organizationId().equals(o)&&x.manufacturerPartnerId().equals(m)&&x.code().equalsIgnoreCase(c));}public boolean rackCodeExists(DomainIdentifier r,String c){return racks.values().stream().anyMatch(x->x.roomId().equals(r)&&x.code().equalsIgnoreCase(c));}public boolean serialExists(String s){return equipment.values().stream().anyMatch(x->s.equals(x.serialNumber()));}public Optional<EquipmentModel> model(DomainIdentifier id){return Optional.ofNullable(models.get(id));}public Optional<Rack> rack(DomainIdentifier id){return Optional.ofNullable(racks.get(id));}public Optional<Equipment> equipment(DomainIdentifier id){return Optional.ofNullable(equipment.get(id));}public Optional<PhysicalPort> port(DomainIdentifier id){var p=ports.get(id);return p==null?Optional.empty():Optional.of(new PhysicalPort(p.id(),p.organizationId(),p.equipmentId(),p.name(),p.kind(),p.media(),p.connector(),portConnected(id)));}public Optional<CableConnection> cable(DomainIdentifier id){return Optional.ofNullable(cables.get(id));}public List<EquipmentModel> models(DomainIdentifier o,int l){return models.values().stream().filter(x->x.organizationId().equals(o)).limit(l).toList();}public List<Rack> racks(DomainIdentifier o,DomainIdentifier r,int l){return racks.values().stream().filter(x->x.organizationId().equals(o)&&(r==null||x.roomId().equals(r))).limit(l).toList();}public List<Equipment> equipment(DomainIdentifier o,DomainIdentifier r,int l){return equipment.values().stream().filter(x->x.organizationId().equals(o)&&(r==null||x.rackId().equals(r))).limit(l).toList();}public List<PhysicalPort> ports(DomainIdentifier e){return ports.values().stream().filter(x->x.equipmentId().equals(e)).map(x->new PhysicalPort(x.id(),x.organizationId(),x.equipmentId(),x.name(),x.kind(),x.media(),x.connector(),portConnected(x.id()))).toList();}public List<CableConnection> cables(DomainIdentifier o,int l){return cables.values().stream().filter(x->x.organizationId().equals(o)).limit(l).toList();}public void lockRackForOccupancy(DomainIdentifier r){rackLocks++;}public void lockPortsForConnection(DomainIdentifier a,DomainIdentifier b){portLocks++;}public boolean footprintOccupied(DomainIdentifier r,int start,int end,DomainIdentifier excluding){for(var e:equipment.values()){if(e.rackId().equals(r)&&(excluding==null||!e.id().equals(excluding))&&(e.status()==PhysicalStatus.ACTIVE||e.status()==PhysicalStatus.MAINTENANCE)){int eu=models.get(e.modelId()).rackUnits(),ee=e.startU()+eu-1;if(e.startU()<=end&&ee>=start)return true;}}return false;}public boolean equipmentHasActiveCable(DomainIdentifier e){var ids=ports.values().stream().filter(p->p.equipmentId().equals(e)).map(PhysicalPort::id).toList();return cables.values().stream().anyMatch(c->c.status()==PhysicalStatus.ACTIVE&&(ids.contains(c.portAId())||ids.contains(c.portBId())));}public boolean portConnected(DomainIdentifier p){return cables.values().stream().anyMatch(c->c.status()==PhysicalStatus.ACTIVE&&(p.equals(c.portAId())||p.equals(c.portBId())));}public void insertModel(EquipmentModel x){models.put(x.id(),x);}public void updateModel(EquipmentModel x,long v){check(models.get(x.id()).version(),v);models.put(x.id(),x);}public void insertRack(Rack x){racks.put(x.id(),x);}public void updateRack(Rack x,long v){check(racks.get(x.id()).version(),v);racks.put(x.id(),x);}public void insertEquipment(Equipment x,List<PhysicalPort> ps){equipment.put(x.id(),x);ps.forEach(p->ports.put(p.id(),p));}public void updateEquipment(Equipment x,long v){check(equipment.get(x.id()).version(),v);equipment.put(x.id(),x);}public void insertCable(CableConnection x){cables.put(x.id(),x);}public void updateCable(CableConnection x,long v){check(cables.get(x.id()).version(),v);cables.put(x.id(),x);}private void check(long a,long b){if(a!=b)throw new DcimPhysicalConflictException("VERSION_CONFLICT","version");}}
 private static void expect(String code,Action a){try{a.run();}catch(DcimPhysicalConflictException e){require(code.equals(e.code()),"unexpected code "+e.code());return;}catch(Exception e){throw new AssertionError(e);}throw new AssertionError("expected "+code);}private static void require(boolean c,String m){if(!c)throw new AssertionError(m);}@FunctionalInterface interface Action{void run()throws Exception;}
}
